<div class="d-flex justify-content-between mb-4"><h1 class="h3">Products</h1><a class="btn btn-success" href="<?= url_to('admin.products.create') ?>">Add Product</a></div>
<form class="card border-0 p-3 mb-3" method="get"><div class="row g-2"><div class="col-lg-4"><input class="form-control" name="q" value="<?= esc($filters['q']) ?>" placeholder="Name, code, or SKU"></div><div class="col"><select class="form-select" name="category_id"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $filters['category']===$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select></div><div class="col"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['draft','active','inactive','out_of_stock'] as $s): ?><option value="<?= $s ?>"><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach ?></select></div><div class="col"><select class="form-select" name="type"><option value="">All types</option><option value="simple">Simple</option><option value="variant">Variant</option></select></div><div class="col-auto"><button class="btn btn-success">Filter</button></div></div></form>
<form method="post" action="<?= site_url('admin/products/bulk') ?>"><?= csrf_field() ?><div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><input class="form-check-input" type="checkbox" onclick="document.querySelectorAll('.product-check').forEach(x=>x.checked=this.checked)"></th><th>Image</th><th>Code / Name</th><th>Category</th><th>Type</th><th>Price</th><th>Stock</th><th>Status</th><th>Featured</th><th>Updated</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><input class="form-check-input product-check" type="checkbox" name="ids[]" value="<?= $p['id'] ?>"></td><td><?php if($p['main_image']): ?><img src="<?= base_url($p['main_image']) ?>" width="48" height="48" class="rounded object-fit-cover" alt=""><?php else: ?>—<?php endif ?></td><td><small class="text-muted"><?= esc($p['product_code']) ?></small><br><strong><?= esc($p['name']) ?></strong></td><td><?= esc($p['category_name']??'—') ?></td><td><?= ucfirst($p['stock_type']) ?></td><td>৳<?= number_format((float)($p['sale_price']?:$p['regular_price']),2) ?></td><td><?= $p['stock_type']==='variant'?'By variant':(int)$p['stock_quantity'] ?></td><td><span class="badge text-bg-<?= $p['status']==='active'?'success':'secondary' ?>"><?= esc($p['status']) ?></span></td><td><?= $p['featured']?'Yes':'No' ?></td><td><?= esc($p['updated_at']) ?></td><td><a class="btn btn-sm btn-outline-success" href="<?= url_to('admin.products.show',$p['id']) ?>">View</a> <a class="btn btn-sm btn-outline-primary" href="<?= url_to('admin.products.edit',$p['id']) ?>">Edit</a></td></tr><?php endforeach ?><?php if(!$products): ?><tr><td colspan="11" class="text-center text-muted py-4">No products found.</td></tr><?php endif ?></tbody></table></div></div><div class="d-flex gap-2 mt-3"><select class="form-select w-auto" name="action" required><option value="">Bulk action</option><option value="activate">Activate</option><option value="deactivate">Deactivate</option><option value="feature">Mark Featured</option><option value="unfeature">Remove Featured</option><option value="delete">Soft Delete</option></select><button class="btn btn-outline-success">Apply</button><div class="ms-auto"><?= $pager->links() ?></div></div></form>
